      "code": "n = int(text)",
      "note": "This fails: abc isn't a number."
     },
     {
      "code": "print(\"Double is\", n * 2)",
      "note": "Skipped, because the line above failed."
     },
     {
      "code": "except ValueError:",
      "note": "Catches that exact kind of error."
     },
     {
      "code": "print(\"That is not a number\")",
      "note": "Runs instead of crashing."
     }
    ],
